-- Philippines: milestones + English translations. Generated by
-- new_country_scaffold.py; INSERT OR IGNORE throughout (idempotent).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'ph-train-law-2018', id, '2018-01-01', 1, 'https://www.officialgazette.gov.ph/2017/12/27/republic-act-no-10963/', 0, '[]', NULL, 'none' FROM countries WHERE code = 'PH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-train-law-2018', 'en', 'TRAIN Law amends the NIRC (RA 10963)', 'The Tax Reform for Acceleration and Inclusion Act amended Sections 237 and 237-A of the National Internal Revenue Code, authorizing the Bureau of Internal Revenue to require electronic invoices/receipts and near-real-time electronic sales reporting from large taxpayers and exporters. This established the legal basis for everything that followed, but created no live invoicing obligation on its own -- the BIR still had to write implementing rules and build the system.', '["No action required yet -- this is the enabling law, not an operative mandate.", "Large taxpayers and exporters should note they were named as the eventual target population from the outset."]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'ph-lt100-pilot-2022', id, '2022-07-01', 0, 'https://bir-cdn.bir.gov.ph/local/pdf/RR%208-2022.pdf', 0, '[]', NULL, 'none' FROM countries WHERE code = 'PH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-lt100-pilot-2022', 'en', 'RR 8-2022 launches the LT100 pilot', 'Revenue Regulations No. 8-2022 issued the first implementing rules for the TRAIN Law''s e-invoicing provisions, and the BIR launched a voluntary pilot with 100 selected large taxpayers ("LT100") on the Electronic Invoicing/Receipting System (EIS) from 1 July 2022. Technical and capacity problems forced the BIR to pause the program later that year, and it stayed stalled for roughly two years before formally resuming under RR 11-2025.', '["Pilot participation was by BIR selection only -- no general obligation existed during this phase.", "Businesses outside the pilot had nothing to do yet."]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'ph-mandate-resumed-2025', id, '2025-02-27', 0, 'https://www.pwc.com/ph/en/tax/tax-publications/taxwise-or-otherwise/2025/paperles-invoicing-and-sales-reporting.html', 0, '[]', NULL, 'b2b' FROM countries WHERE code = 'PH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-mandate-resumed-2025', 'en', 'RR 11-2025 formally resumes and expands the mandate', 'Following the CREATE MORE law, Revenue Regulations No. 11-2025 formally resumed the stalled e-invoicing program and set the covered-taxpayer list actually in force today: Large Taxpayers, e-commerce/digital businesses of any size, exporters, users of Computerized Accounting Systems or POS systems with e-invoicing capability, and tax-incentive-holding Registered Business Enterprises. It gave covered taxpayers one year to comply -- a 14 March 2026 deadline that was itself superseded before it arrived (see RR 26-2025).', '["Confirm whether your business falls into one of the newly-covered categories -- the list is broader than \"large taxpayers\" alone.", "Micro enterprises (annual gross sales below PHP 3 million) remain exempt but may opt in voluntarily for cost-deduction incentives."]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'ph-phase1-deadline-2026', id, '2026-12-31', 0, 'https://bir-cdn.bir.gov.ph/BIR/pdf/RR%20No.%2026-2025%20Digest.pdf', 1, '[{"label": "BIR Electronic Invoicing System (EIS)", "url": "https://eis.bir.gov.ph/"}]', 'expected', 'b2b' FROM countries WHERE code = 'PH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-phase1-deadline-2026', 'en', 'RR 26-2025 extends Phase 1 to 31 December 2026', 'Revenue Regulations No. 26-2025 pushed the Phase 1 compliance deadline from 14 March 2026 to 31 December 2026 -- roughly nine and a half months'' extra runway for the taxpayers named under RR 11-2025. Industry sources describe the practical effect as e-invoicing becoming mandatory from 1 January 2027. This is the second time this specific deadline has moved (the mandate itself was also paused for about two years after its 2022 pilot), so treat the date as the current official target rather than a settled certainty.', '["Covered taxpayers: have structured, machine-readable e-invoices (not PDFs) ready to issue by the deadline.", "Confirm your invoicing/POS/CAS software can produce the required structured data format.", "Watch for further BIR guidance -- the deadline has already moved once and the transmission platform (ESRS) is still being built."]');
